	@Test
	void nestedQueryInSourceCallbackRestoresOuterReadAndEarlyClosePullsNoMoreRows(@TempDir File directory) {
		var store = new CallbackStore(directory);
		var repository = new SailRepository(store);
		try (var connection = repository.getConnection()) {
			seed(connection);
			try (var result = connection.prepareTupleQuery(QUERY).evaluate()) {
				result.next();
				AtomicInteger nextCalls = new AtomicInteger();
				Consumer<Pull> reenter = phase -> {
					var initializer = QueryExecutionContext.getExternalValueInitializer();
					assertNotNull(initializer);
					if (phase == Pull.AVAILABILITY) {
						// The nested source must not share this result's handoff.
						Consumer<Pull> current = store.callback;
						store.callback = ignored -> {
						};
						try (var nested = connection.prepareTupleQuery("SELECT ?n WHERE { VALUES ?n { 7 } }")
								.evaluate()) {
							assertEquals("7", nested.next().getValue("n").stringValue());
						} finally {
							store.callback = current;
						}
						assertSame(initializer, QueryExecutionContext.getExternalValueInitializer());
						assertEquals(1, store.activeReads.get());
					} else {
						nextCalls.incrementAndGet();
					}
				};
				store.callback = reenter;
				assertTrue(result.hasNext());
				assertEquals(1, nextCalls.get());
				assertEquals(0, store.activeReads.get());
				result.close();
				assertEquals(1, nextCalls.get());
				assertFalse(result.hasNext());
			}
		} finally {
			repository.shutDown();
		}
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void crossThreadCloseOrCancellationRetiresWorkerAdmission(boolean cancel, @TempDir File directory)
			throws Exception {
		var store = new CallbackStore(directory);
		var repository = new SailRepository(store);
		try (var connection = repository.getConnection(); var worker = Executors.newVirtualThreadPerTaskExecutor()) {
			seed(connection);
			try (var result = connection.prepareTupleQuery(QUERY).evaluate()) {
				result.next();
				var entered = new CountDownLatch(1);
				var release = new CountDownLatch(1);
				var captured = new AtomicReference<QueryExecutionContext.ReplayContext>();
				store.callback = phase -> {
					if (phase == Pull.VALUE) {
						captured.set(QueryExecutionContext.captureReplayContext());
						entered.countDown();
						try {
							assertTrue(release.await(10, TimeUnit.SECONDS));
						} catch (InterruptedException failure) {
							Thread.currentThread().interrupt();
							throw new QueryInterruptedException("Interrupted during late value capture", failure);
						}
					}
				};
				var reading = worker.submit(result::hasNext);
				try {
					assertTrue(entered.await(10, TimeUnit.SECONDS));
					assertNotNull(captured.get());
					captured.get().checkActive();
					if (cancel) {
						assertTrue(CooperativeCancellation.forward(result));
					} else {
						result.close();
						assertEquals(1, store.activeReads.get(), "The admitted row still owns its native context");
					}
					assertThrows(SailException.class, captured.get()::checkActive);
				} finally {
					release.countDown();
				}
				if (cancel) {
					assertInstanceOf(QueryInterruptedException.class,
							assertThrows(ExecutionException.class, () -> reading.get(10, TimeUnit.SECONDS)).getCause());
				} else {
					assertFalse(reading.get(10, TimeUnit.SECONDS));
				}
				assertEquals(0, store.activeReads.get());
			}
		} finally {
			repository.shutDown();
		}
	}

	private static void seed(RepositoryConnection connection) {
		seed(connection, 4);
	}

	private static void seed(RepositoryConnection connection, int rows) {
		var values = connection.getValueFactory();
		var predicate = values.createIRI("urn:observed-read:p");
		connection.begin();
		for (int i = 0; i < rows; i++) {
			connection.add(values.createIRI("urn:observed-read:s" + i), predicate, values.createLiteral(i));
		}
		connection.commit();
	}

	private enum Pull {
		AVAILABILITY,
		VALUE
	}

	private static final class CallbackStore extends ObservedStore {
		private volatile Consumer<Pull> callback = ignored -> {
		};
		private Runnable onSourceClose = () -> {
		};

		private CallbackStore(File directory) {
			super(directory);
		}

		@Override
		protected NotifyingSailConnection getConnectionInternal() {
			return new LmdbStoreConnection(this) {
				@Override
				protected <T, E extends Exception> CloseableIteration<T> registerIteration(
						CloseableIteration<T> source) {
					Runnable closeCallback = onSourceClose;
					return super.registerIteration(new IterationWrapper<>(source) {
						@Override
						public boolean hasNext() {
							if (super.hasNext()) {
								callback.accept(Pull.AVAILABILITY);
								return true;
							}
							return false;
						}

						@Override
						public T next() {
							T row = super.next();
							callback.accept(Pull.VALUE);
							return row;
						}

						@Override
						protected void handleClose() {
							try {
								super.handleClose();
							} finally {
								closeCallback.run();
							}
						}
					});
				}
			};
		}
	}

	private static class ObservedStore extends LmdbStore {
		final AtomicInteger readActivations = new AtomicInteger();
		final AtomicInteger activeReads = new AtomicInteger();

		private ObservedStore(File directory) {
			this(directory, true);
		}

		private ObservedStore(File directory, boolean nativeEvaluation) {
			super(directory, new LmdbStoreConfig("spoc,posc,ospc").setNativeEvaluationEnabled(nativeEvaluation)
					.setDirectAdjacencyEnabled(false));
		}

		@Override
		LmdbSailStore createBackingStore(File directory, StoreProperties properties, LmdbStoreConfig config,
				boolean sketchBasedJoinEstimatorEnabled) throws IOException {
			return new LmdbSailStore(directory, properties, config, sketchBasedJoinEstimatorEnabled,
					valueStoreFactory(), TripleStore::new) {
				@Override
				void readResourceContextEntered() {
					readActivations.incrementAndGet();
					activeReads.incrementAndGet();
				}

				@Override
				void readResourceContextLeft() {
					activeReads.decrementAndGet();
				}
			};
		}

		LmdbSailStore.ValueStoreFactory valueStoreFactory() {
			return null;
		}
	}

	private static final class FailingBufferedStore extends ObservedStore {
		private final SailException failure = new SailException("Unable to decode the fifth scanned statement");
		private Thread failOnThread;
		private int scanned;

		private FailingBufferedStore(File directory) {
			super(directory, false);
		}

		@Override
		LmdbSailStore.ValueStoreFactory valueStoreFactory() {
			return (directory, properties, config) -> new ValueStore(directory, properties, config) {
				private int created;

				// A private scan hands out statements whose values are created when their row is converted, so
				// the fault is injected where the first of a statement's two projected values is created.
				@Override
				LmdbValue getLazyValue(long id, ValueStoreRevision revision, ValueResolutionScope exposure,
						Value supplied, long semanticVersion) throws IOException {
					if (Thread.currentThread() == failOnThread && created++ % 2 == 0 && ++scanned == 5) {
						throw failure;
					}
					return super.getLazyValue(id, revision, exposure, supplied, semanticVersion);
				}
			};
		}
	}
